.chip-filter {
  display: grid;
  gap: 0.5em;
  font: inherit;
  color: var(--ink);
}

.chip-filter__label {
  font-size: clamp(0.75rem, 0.7rem + 0.2vw, 0.875rem);
  color: var(--muted);
}

.chip-filter__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5em;
}

.chip-filter__chip {
  font: inherit;
  font-size: clamp(0.8125rem, 0.75rem + 0.25vw, 1rem);
  line-height: 1.2;
  padding: 0.4em 0.9em;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.chip-filter__chip:hover {
  background: var(--myelin-wash);
  border-color: var(--myelin);
}

.chip-filter__chip[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
}

.chip-filter__chip[aria-pressed="true"]:hover {
  background: var(--myelin);
  border-color: var(--myelin);
}

.chip-filter__chip:focus-visible {
  border-color: var(--myelin);
}

:root[data-motion="reduce"] .chip-filter__chip {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip {
    transition: none;
  }
}
